#include <math.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static void emit(double value) { uint64_t bits; memcpy(&bits, &value, sizeof(bits)); printf("%016llx", (unsigned long long)bits); }
int main(void) { char line[256]; while (fgets(line,sizeof(line),stdin)) { double value=strtod(line,NULL); emit(value); putchar(' '); emit(acos(value)); putchar(' '); emit(log1p(value)); putchar('\n'); } return 0; }
